package org.transittr.tests;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;
public class MapCheck extends Instrumentation {
 private Activity a;private int peak,samples;private volatile boolean measuring;private Thread sampler;
 private Object field(String n)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(a);}private void set(String n,Object v)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);f.set(a,v);}private void call(String n)throws Exception{Method m=a.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(a);}
 private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 private void report(String s){Bundle b=new Bundle();b.putString("stream",s+"\n");sendStatus(1,b);}
 private void sample(){Debug.MemoryInfo info=new Debug.MemoryInfo();Debug.getMemoryInfo(info);peak=Math.max(peak,info.getTotalPss());samples++;}
 private void screen(final int city,final int tab)throws Exception{runOnMainSync(new Runnable(){public void run(){try{call("stopTracking");set("snapshot",null);set("city",city);set("screen",tab);set("selectedRail",null);call("build");}catch(Exception e){throw new RuntimeException(e);}}});waitForIdleSync();Thread.sleep(600);}
 private int positions()throws Exception{Object s=field("snapshot");return s==null?0:((Integer)s.getClass().getMethod("positionCount").invoke(s)).intValue();}
 private long received()throws Exception{Object s=field("snapshot");return s==null?0:s.getClass().getField("receivedAt").getLong(s);}
 private void start(final String stop,final String line)throws Exception{runOnMainSync(new Runnable(){public void run(){try{((EditText)field("stopInput")).setText(stop);((EditText)field("lineInput")).setText(line);((Button)field("start")).performClick();}catch(Exception e){throw new RuntimeException(e);}}});}
 private boolean waitGps()throws Exception{for(int i=0;i<250;i++){Thread.sleep(200);waitForIdleSync();if(positions()>0)return true;if(field("snapshot")!=null&&!((Boolean)field("refreshing")).booleanValue())break;}return false;}
 private void photo(String name)throws Exception{report("CAPTURE="+name);Thread.sleep(6000);}
 private void pauseCheck()throws Exception{final long before=received();runOnMainSync(new Runnable(){public void run(){a.moveTaskToBack(true);}});Thread.sleep(1000);check(!((Boolean)field("resumed")).booleanValue(),"real background pause");Thread.sleep(22000);check(received()==before,"no background polling");final android.app.Instrumentation.ActivityMonitor monitor=addMonitor("org.transittr.TransitActivity",null,false);report("RESUME_FROM_HOME");Activity foreground=monitor.waitForActivityWithTimeout(20000);removeMonitor(monitor);if(foreground!=null)a=foreground;waitForIdleSync();check(((Boolean)field("resumed")).booleanValue(),"foreground resume");report("BACKGROUND_PAUSE_PASS=true");}
 private TextView mapLabel(View v){if(v instanceof TextView&&"Harita".equals(((TextView)v).getText().toString()))return (TextView)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){TextView t=mapLabel(g.getChildAt(i));if(t!=null)return t;}}return null;}
 private void navigationCheck()throws Exception{runOnMainSync(new Runnable(){public void run(){try{TextView t=mapLabel((View)field("root"));check(t!=null&&t.getCompoundDrawables()[1]!=null,"Material map icon above label");}catch(Exception e){throw new RuntimeException(e);}}});report("MATERIAL_MAP_ICON_PASS=true");}
 private void stationCheck()throws Exception{runOnMainSync(new Runnable(){public void run(){try{check(field("selectedRail")!=null,"line selected");((android.widget.LinearLayout)field("railRows")).getChildAt(0).performClick();Object map=field("map");check(((Integer)map.getClass().getMethod("zoomLevel").invoke(map)).intValue()==16,"station focus");}catch(Exception e){throw new RuntimeException(e);}}});report("STATION_FOCUS_PASS=true");}
 private void estimateChecks()throws Exception{ClassLoader loader=a.getClassLoader();Class<?> metro=loader.loadClass("org.transittr.MetroData"),engine=loader.loadClass("org.transittr.RailEstimator"),lineType=loader.loadClass("org.transittr.JourneyData$RailLine"),stationType=loader.loadClass("org.transittr.JourneyData$Station");Object route=lineType.newInstance();ArrayList stations=(ArrayList)lineType.getField("stations").get(route);java.lang.reflect.Constructor station=stationType.getConstructor(String.class,Double.TYPE,Double.TYPE);stations.add(station.newInstance("A",40.0,30.0));stations.add(station.newInstance("B",40.0,30.01));stations.add(station.newInstance("C",40.0,30.02));Method point=engine.getMethod("position",lineType,Integer.TYPE,Double.TYPE,Integer.TYPE,Integer.TYPE);Object v=point.invoke(null,route,0,60.0,120,20);check(Math.abs(v.getClass().getField("lon").getDouble(v)-30.01)<.00001,"intermediate dwell");check(v.getClass().getField("estimated").getBoolean(v),"estimated marker explicit");v=point.invoke(null,route,1,0.0,120,20);check(Math.abs(v.getClass().getField("lon").getDouble(v)-30.02)<.00001,"reverse direction starts at other terminal");check(point.invoke(null,route,0,-1.0,120,20)==null,"not departed");check(point.invoke(null,route,0,120.0,120,20)==null,"completed trip removed");Calendar clock=Calendar.getInstance(TimeZone.getTimeZone("GMT+03:00"));clock.clear();clock.set(2026,10,5,12,0,0);Method lines=metro.getMethod("lines",android.content.Context.class,Integer.TYPE),estimate=engine.getMethod("estimate",android.content.Context.class,Integer.TYPE,lineType,ArrayList.class,Long.TYPE);for(int city=0;city<2;city++){ArrayList all=(ArrayList)lines.invoke(null,a,city);Object chosen=null;for(Object l:all)if((city==0?"M1":"M2").equals(lineType.getField("id").get(l)))chosen=l;Object result=estimate.invoke(null,a,city,chosen,all,clock.getTimeInMillis());check(((ArrayList)result.getClass().getField("trains").get(result)).size()>0,"daytime estimated trains city "+city);}report("ESTIMATE_MODEL_PASS=7");}
 private void fixtures()throws Exception{ClassLoader loader=a.getClassLoader();Class<?> tracker=loader.loadClass("org.transittr.TrackingClient");Method ego=tracker.getMethod("ankara",String.class,String.class);String raw="{\"status\":\"TRUE\",\"table\":[{\"arac_no\":\"T\",\"hat_no\":\"591\",\"hat_ad\":\"TEST\",\"lat\":\"39.9\",\"lng\":\"32.8\",\"saniye\":\"120\"}]}";Object s=ego.invoke(null,raw,"");check(((Integer)s.getClass().getMethod("positionCount").invoke(s)).intValue()==1,"EGO coordinate parse");s=ego.invoke(null,raw.replace("39.9","0"),"");check(((Integer)s.getClass().getMethod("positionCount").invoke(s)).intValue()==0,"invalid coordinates rejected");Class<?> metro=loader.loadClass("org.transittr.MetroData");Method lines=metro.getMethod("lines",android.content.Context.class,Integer.TYPE);ArrayList ankara=(ArrayList)lines.invoke(null,a,0),istanbul=(ArrayList)lines.invoke(null,a,1);check(ankara.size()==5,"Ankara 5 rail lines");check(istanbul.size()==19,"Istanbul 19 rail lines");boolean m11=false;for(Object r:istanbul)if("M11".equals(r.getClass().getField("id").get(r)))m11=true;check(m11,"M11 present");Class<?> map=loader.loadClass("org.transittr.OsmMapView");Method x=map.getDeclaredMethod("wx",Double.TYPE,Integer.TYPE);x.setAccessible(true);check(Math.abs(((Double)x.invoke(null,0.0,0)).doubleValue()-128)<.0001,"Mercator origin");report("FIXTURES_PASS=6; ANKARA_RAIL=5; ISTANBUL_RAIL=19");}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();boolean pass=false;try{measuring=true;sampler=new Thread(new Runnable(){public void run(){while(measuring){sample();try{Thread.sleep(100);}catch(Exception e){break;}}}});sampler.start();a=startActivitySync(new Intent().setClassName("org.transittr","org.transittr.TransitActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();fixtures();estimateChecks();navigationCheck();screen(0,0);start("10940","");boolean ego=waitGps();report("ANKARA_GPS="+ego+"; VEHICLES="+positions());check(ego,"Ankara real GPS required");long first=received();photo("ANKARA_MAP");boolean refreshed=false;for(int i=0;i<140;i++){Thread.sleep(200);if(received()>first){refreshed=true;break;}}check(refreshed,"foreground auto refresh");report("AUTO_REFRESH_PASS=true");pauseCheck();screen(0,1);photo("ANKARA_METRO");stationCheck();screen(1,0);start("224672","500T");boolean ist=waitGps();report("ISTANBUL_GPS="+ist+"; VEHICLES="+positions());check(ist,"Istanbul real GPS required");photo("ISTANBUL_MAP");screen(1,1);photo("ISTANBUL_METRO");screen(0,2);photo("SETTINGS");sample();check(peak<195312,"PSS below 200 MB");pass=true;out.putString("stream","PASS Android "+Build.VERSION.RELEASE+" API "+Build.VERSION.SDK_INT+"; PEAK_PSS_KIB="+peak+"; SAMPLES="+samples+"; REAL_GPS_CITIES=2/2; AUTO_REFRESH=true; BACKGROUND_PAUSE=true; MATERIAL_MAP_ICON=true; STATION_FOCUS=true\n");}catch(Throwable t){java.io.StringWriter sw=new java.io.StringWriter();t.printStackTrace(new java.io.PrintWriter(sw));out.putString("stream","FAIL API="+Build.VERSION.SDK_INT+"; PEAK_PSS_KIB="+peak+"\n"+sw.toString());}finally{measuring=false;if(sampler!=null)sampler.interrupt();}finish(pass?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
}
